import{_ as a,o as r,c as d,a2 as e}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"शिकार-विरोध का मूल सिद्धांत-पत्र","description":"","frontmatter":{},"headers":[],"relativePath":"hi/04-反掠夺主义核心论纲.md","filePath":"hi/04-反掠夺主义核心论纲.md","lastUpdated":null}'),i={name:"hi/04-反掠夺主义核心论纲.md"};function o(l,t,h,n,s,u){return r(),d("div",null,[...t[0]||(t[0]=[e('<h1 id="शिकार-विरोध-का-मूल-सिद्धांत-पत्र" tabindex="-1">शिकार-विरोध का मूल सिद्धांत-पत्र <a class="header-anchor" href="#शिकार-विरोध-का-मूल-सिद्धांत-पत्र" aria-label="Permalink to &quot;शिकार-विरोध का मूल सिद्धांत-पत्र&quot;">​</a></h1><table tabindex="0"><thead><tr><th>मद</th><th>सामग्री</th></tr></thead><tbody><tr><td>दस्तावेज़ संख्या</td><td>04</td></tr><tr><td>मॉड्यूल</td><td>सामान्य सिद्धांत और मूल सेटिंग्स</td></tr><tr><td>कीवर्ड</td><td>शिकार-विरोध, शिकार की आलोचना, सहजीवी विकल्प, नैतिक सीमा, प्रणालीगत क्रांति</td></tr></tbody></table><h2 id="i-शिकारवाद-की-परिभाषा-और-अभिव्यक्तियाँ" tabindex="-1">I. शिकारवाद की परिभाषा और अभिव्यक्तियाँ <a class="header-anchor" href="#i-शिकारवाद-की-परिभाषा-और-अभिव्यक्तियाँ" aria-label="Permalink to &quot;I. शिकारवाद की परिभाषा और अभिव्यक्तियाँ&quot;">​</a></h2><p>शिकारवाद वह ब्रह्मांड-दृष्टि और साधना प्रणाली है जो अन्य जीवन या विमानों के मूल स्रोत, ऊर्जा, भाग्य और संसाधनों के बिना-मुआवज़ा अधिग्रहण, निगलन और शोषण को अपना केंद्रीय साधन बनाती है, ताकि स्वयं या अपने समूह का विकास प्राप्त हो सके। शिकारवाद कोई विशिष्ट साधना-विधि नहीं, बल्कि साधना दर्शन, सामाजिक संस्थाओं और सभ्यतागत संबंधों में व्याप्त एक मौलिक रुख है।</p><p>हेंग युआनझोउ के इतिहास में, शिकारवाद निम्नलिखित मुख्य रूपों में प्रकट हुआ:</p><table tabindex="0"><thead><tr><th>रूप</th><th>अभिव्यक्ति</th><th>हानि</th></tr></thead><tbody><tr><td>ऊर्जा-शिकार</td><td>अन्य जीवन की साधना ऊर्जा या मूल स्रोत को सीधे निगलना</td><td>शिकार-पीड़ित की मृत्यु या साधना-विनाश का कारण; ब्रह्मांडीय ऊर्जा-संचार टूट जाता है</td></tr><tr><td>भाग्य-शिकार</td><td>गुप्त विद्याओं से दूसरों या जातियों का भाग्य चुराना</td><td>शिकार-पीड़ित के भाग्य का पतन और जातीय ह्रास</td></tr><tr><td>विधि-एकाधिकार</td><td>कुछ संप्रदाय साधना-विधियों का एकाधिकार कर, संचरण के बदले निष्ठा और संसाधन लेते हैं</td><td>वर्ग-कठोरीकरण; निचले प्राणी विकास पथ खो देते हैं</td></tr><tr><td>विमान-उपनिवेशीकरण</td><td>उच्च विमान निम्न विमानों को जीतकर उनके संसाधन और जनसंख्या लूटते हैं</td><td>विमान-झिल्ली को क्षति और विमान पारिस्थितिकी का पतन</td></tr><tr><td>आत्मिक दासता</td><td>आत्मा-नियंत्रण द्वारा अन्य जीवन को साधना-उपकरण बनाना</td><td>दास बनाए गए की स्वतंत्र इच्छा छीनना, जीवन की गरिमा का उल्लंघन</td></tr><tr><td>संसाधन-दोहन</td><td>किसी ग्रह या विमान के संसाधनों का असंयमित दोहन</td><td>पारिस्थितिक विलुप्ति और त्वरित ब्रह्मांडीय एंट्रॉपी</td></tr></tbody></table><h2 id="ii-शिकारवाद-के-मौलिक-भ्रम" tabindex="-1">II. शिकारवाद के मौलिक भ्रम <a class="header-anchor" href="#ii-शिकारवाद-के-मौलिक-भ्रम" aria-label="Permalink to &quot;II. शिकारवाद के मौलिक भ्रम&quot;">​</a></h2><p>शिकार-विरोध मानता है कि शिकारवाद में तीन मौलिक भ्रम हैं:</p><h3 id="_2-1-ब्रह्मांड-दृष्टि-भ्रम-ब्रह्मांड-को-सीमित-शिकार-क्षेत्र-मानना" tabindex="-1">2.1 ब्रह्मांड-दृष्टि भ्रम: ब्रह्मांड को सीमित शिकार-क्षेत्र मानना <a class="header-anchor" href="#_2-1-ब्रह्मांड-दृष्टि-भ्रम-ब्रह्मांड-को-सीमित-शिकार-क्षेत्र-मानना" aria-label="Permalink to &quot;2.1 ब्रह्मांड-दृष्टि भ्रम: ब्रह्मांड को सीमित शिकार-क्षेत्र मानना&quot;">​</a></h3><p>शिकारी ब्रह्मांड-दृष्टि ब्रह्मांड को सीमित संसाधनों का शिकार-क्षेत्र मानती है, यह विश्वास करते हुए कि विकास अनिवार्य रूप से शून्य-योग खेल है और शक्तिशाली की उन्नति कमजोर के बलिदान की कीमत पर होनी चाहिए। यह दृष्टि ब्रह्मांड की स्वयं की &quot;विकासशीलता&quot; को अनदेखा करती है — ब्रह्मांड संसाधनों का कोई स्थिर पात्र नहीं, बल्कि एक जीवित प्राणी है जो व्यवस्थित सहजीवन के माध्यम से समग्र आयामी उन्नति में सक्षम है। जब शिकारी कमजोरों को निगलते हैं, वे न केवल कमजोरों की ऊर्जा, बल्कि ब्रह्मांड की समग्र विकास क्षमता को भी समाप्त करते हैं।</p><h3 id="_2-2-नैतिक-भ्रम-शक्तिशाली-के-विकास-अधिकार-को-कमजोर-के-जीवन-अधिकार-से-ऊपर-रखना" tabindex="-1">2.2 नैतिक भ्रम: शक्तिशाली के विकास-अधिकार को कमजोर के जीवन-अधिकार से ऊपर रखना <a class="header-anchor" href="#_2-2-नैतिक-भ्रम-शक्तिशाली-के-विकास-अधिकार-को-कमजोर-के-जीवन-अधिकार-से-ऊपर-रखना" aria-label="Permalink to &quot;2.2 नैतिक भ्रम: शक्तिशाली के विकास-अधिकार को कमजोर के जीवन-अधिकार से ऊपर रखना&quot;">​</a></h3><p>शिकारवाद &quot;बलवान दुर्बल को खाता है&quot; को प्राकृतिक नियम मानता है, यह विश्वास करते हुए कि शक्तिशाली को कमजोर को निगलने का अधिकार और कर्तव्य भी है। यह नैतिक दृष्टि प्राकृतिक चयन और नैतिक चयन को भ्रमित करती है। प्रकृति में बलवान का दुर्बल को खाना अचेतन पारिस्थितिक नियम है; पर सचेत साधना सभ्यताओं में, शक्तिशाली के पास चयन की क्षमता होती है और इसलिए चयन की जिम्मेदारी भी। &quot;स्वर्ग-मार्ग&quot; के बहाने किया गया शिकार, मूलतः शक्तिशाली द्वारा अपने लोभ को ब्रह्मांडीय नियम के रूप में प्रस्तुत करना है।</p><h3 id="_2-3-दक्षता-भ्रम-शिकार-को-सबसे-तेज़-विकास-पथ-मानना" tabindex="-1">2.3 दक्षता भ्रम: शिकार को सबसे तेज़ विकास पथ मानना <a class="header-anchor" href="#_2-3-दक्षता-भ्रम-शिकार-को-सबसे-तेज़-विकास-पथ-मानना" aria-label="Permalink to &quot;2.3 दक्षता भ्रम: शिकार को सबसे तेज़ विकास पथ मानना&quot;">​</a></h3><p>शिकारवाद दावा करता है कि शिकार सबसे तेज़ और सबसे कुशल विकास पथ है। पर दीर्घावधि में, शिकारी विकास गंभीर &quot;दक्षता-छत&quot; से ग्रस्त है: पहला, शिकार से प्राप्त ऊर्जा अक्सर मूल स्वामी की अवशिष्ट इच्छा ले जाती है, जिसके शोधन और शुद्धिकरण के लिए अपार प्रयास चाहिए; दूसरा, शिकारी कृत्य शिकार-पीड़ित और उनके संबद्ध समूहों का प्रतिरोध भड़काते हैं, साधना की बाह्य लागत बढ़ाते हैं; तीसरा, शिकार पर दीर्घकालिक निर्भरता साधक की स्वयं की मूल-आधारित विकास क्षमता को ह्रासित करती है, शिकार अनुपलब्ध होने पर ठहराव लाती है; चौथा, शिकारी साधक अक्सर परम स्तर की सफलता पर &quot;अशुद्ध मूल&quot; की अड़चन का सामना करते हैं, जिससे ब्रह्मांडीय मूल स्रोत को सचमुच छूना कठिन हो जाता है।</p><h2 id="iii-शिकार-विरोध-के-मूल-प्रस्ताव" tabindex="-1">III. शिकार-विरोध के मूल प्रस्ताव <a class="header-anchor" href="#iii-शिकार-विरोध-के-मूल-प्रस्ताव" aria-label="Permalink to &quot;III. शिकार-विरोध के मूल प्रस्ताव&quot;">​</a></h2><p>शिकार-विरोध केवल सभी प्रतिस्पर्धा और अंतर को नकारता नहीं, बल्कि निम्नलिखित मूल प्रस्ताव रखता है:</p><ol><li><strong>विकास शून्य-योग नहीं हो सकता</strong>: सहजीवी चक्रों और लंगर जाल के माध्यम से, दस हजार जातियों का विकास सहक्रियात्मक प्रभाव उत्पन्न कर सकता है, जिसमें सम्पूर्ण अपने भागों के योग से बड़ी विकास-क्षमता प्राप्त होती है।</li><li><strong>प्रतिस्पर्धा रचनात्मक होनी चाहिए, विनाशकारी नहीं</strong>: शिकार-विरोध स्वस्थ प्रतिस्पर्धा का विरोध नहीं करता, पर प्रतिस्पर्धा का रूप स्वयं की रचनात्मक क्षमता बढ़ाना होना चाहिए, प्रतिद्वंद्वी की शिकारी क्षमता को समाप्त करना नहीं।</li><li><strong>शक्तिशाली की जिम्मेदारी उसके अधिकारों से बड़ी है</strong>: साधक का स्तर जितना ऊँचा, सहजीवी जाल के प्रति उसकी जिम्मेदारी उतनी बड़ी, न कि शिकार का अधिकार उतना बड़ा। उन्नत साधकों का कर्तव्य है कनिष्ठ साधकों का मार्गदर्शन, लंगर स्थिरता का अनुरक्षण और सभ्यतागत सुरक्षा की रक्षा।</li><li><strong>संसाधन सृजन से बढ़ने चाहिए, शिकार से वितरित नहीं</strong>: सहजीवी सभ्यता का केंद्रीय दृष्टिकोण केक को बड़ा करना है, बाँटना नहीं — तकनीकी प्रगति और नियम-प्रयोग से नए साधना संसाधन निरंतर सृजित करना।</li><li><strong>शिकार-विरोध समतावाद नहीं है</strong>: शिकार-विरोध बिना परिश्रम के शिकार का विरोध है, न कि अधिक परिश्रम-अधिक प्रतिफल से उत्पन्न अंतरों का। सहजीवी सभ्यता विकास परिणामों के अंतर को स्वीकार करती है, पर आग्रह करती है कि अंतर स्वयं के प्रयास और योगदान से उत्पन्न होने चाहिए।</li></ol><h2 id="iv-शिकार-विरोध-की-संस्थागत-गारंटियाँ" tabindex="-1">IV. शिकार-विरोध की संस्थागत गारंटियाँ <a class="header-anchor" href="#iv-शिकार-विरोध-की-संस्थागत-गारंटियाँ" aria-label="Permalink to &quot;IV. शिकार-विरोध की संस्थागत गारंटियाँ&quot;">​</a></h2><p>शिकार-विरोध केवल सैद्धांतिक प्रस्ताव नहीं; इसके पास संस्थागत गारंटियों की एक शृंखला है:</p><ul><li><strong>विधिक गारंटी</strong>: सहजीवी संविधान और एकाधिकार-विरोधी कानून शिकारी व्यवहार को स्पष्ट रूप से प्रतिबंधित करते हैं; लंगर न्यायालय के पास शिकार मामलों की अधिकारिता है</li><li><strong>तंत्र गारंटी</strong>: उत्पादन-आधारित अनुबंध प्रणाली सुनिश्चित करती है कि संसाधन वितरण हिंसा पर नहीं, योगदान पर आधारित हो; लंगर जाल असामान्य ऊर्जा प्रवाह की निगरानी करता है</li><li><strong>प्रणाली गारंटी</strong>: तीन सौ मूल साधना प्रणालियाँ सभी सहजीवी संचार सिद्धांतों पर आधारित हैं; कोई शिकारी विधि मौजूद नहीं है</li><li><strong>शैक्षिक गारंटी</strong>: सहजीवी शिक्षा प्रणाली शिकार-विरोध नैतिकता को अनिवार्य विषय बनाती है, शिकारी विचार को जड़ से समाप्त करती है</li><li><strong>निगरानी गारंटी</strong>: दस हजार जातियों के गणराज्य सभा ने शिकार-विरोध समिति स्थापित की है, जो शिकारी व्यवहार की निगरानी और जाँच करती है</li></ul><h2 id="v-अवशिष्ट-शिकारी-ताकतों-के-प्रति-नीति" tabindex="-1">V. अवशिष्ट शिकारी ताकतों के प्रति नीति <a class="header-anchor" href="#v-अवशिष्ट-शिकारी-ताकतों-के-प्रति-नीति" aria-label="Permalink to &quot;V. अवशिष्ट शिकारी ताकतों के प्रति नीति&quot;">​</a></h2><p>ब्रह्मांड में अभी भी विद्यमान अवशिष्ट शिकारी ताकतों के लिए, सहजीवी सभ्यता &quot;पृथक्करण, रूपांतरण, दंड&quot; की त्रि-नीति अपनाती है: जिन शिकारियों ने अभी गंभीर हानि नहीं पहुँचाई, उन्हें नैतिक शिक्षा और प्रणाली-रूपांतरण दिया जाता है, उन्हें सहजीवी प्रणाली से जुड़ने का मार्गदर्शन किया जाता है; जो शिकारी रूपांतरण से इनकार कर सहजीवी व्यवस्था को नुकसान पहुँचाते रहते हैं, उन पर विमान-पृथक्करण और साधना-प्रतिबंध लगाए जाते हैं; जिन शिकारियों ने बड़ी आपदाएँ कीं, उन्हें कानून के अनुसार दंडित किया जाता है। सहजीवी सभ्यता शिकार से शिकार का मुकाबला करने की वकालत नहीं करती; सभी दंड लंगर न्यायालय के निष्पक्ष न्याय से गुजरने चाहिए।</p><h2 id="निष्कर्ष" tabindex="-1">निष्कर्ष <a class="header-anchor" href="#निष्कर्ष" aria-label="Permalink to &quot;निष्कर्ष&quot;">​</a></h2><p>शिकार-विरोध लंगर सहजीवी सभ्यता के सैद्धांतिक आधारशिलाओं में से एक है। यह केवल पुरानी शिकारी प्रणाली की आलोचना नहीं, बल्कि सहजीवी विकास की संभावना का सकारात्मक निर्माण है। शिकार-विरोध का अंतिम लक्ष्य शक्तिशालियों को समाप्त करना नहीं, बल्कि शक्तिशालियों की शक्ति को दस हजार जातियों के साझा विकास की सेवा में लगाना है।</p><h2 id="संबंधित-दस्तावेज़" tabindex="-1">संबंधित दस्तावेज़ <a class="header-anchor" href="#संबंधित-दस्तावेज़" aria-label="Permalink to &quot;संबंधित दस्तावेज़&quot;">​</a></h2><ul><li>01-锚点共生文明宣言 (लंगर सहजीवी सभ्यता घोषणा)</li><li>03-共生文明宪章 (सहजीवी सभ्यता अधिकार-पत्र)</li><li>19-修炼伦理与边界 (साधना नैतिकता और सीमाएँ)</li></ul>',26)])])}const q=a(i,[["render",o]]);export{c as __pageData,q as default};
